CREATE TABLE IF NOT EXISTS research_level_attractor_registry_v1 (
    attractor_key VARCHAR(128) NOT NULL PRIMARY KEY,
    display_name VARCHAR(128) NOT NULL,
    category VARCHAR(64) NOT NULL,
    family VARCHAR(64) NOT NULL,
    numeric_value DECIMAL(30,18) NULL,
    value_expression VARCHAR(128) NULL,
    unit_type VARCHAR(32) NOT NULL,
    description TEXT NOT NULL,
    intended_test_context TEXT NOT NULL,
    validation_status VARCHAR(64) NOT NULL DEFAULT 'UNVALIDATED_RESEARCH',
    is_enabled TINYINT(1) NOT NULL DEFAULT 1,
    sort_order INT NOT NULL DEFAULT 0,
    created_at_utc DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    INDEX idx_research_level_attractor_registry_v1_category (category, family, sort_order),
